/**
 * @name Path Traversal in Library
 * @description Detects file opens with user-controlled paths in a library context
 * @kind problem
 * @problem.severity error
 * @id py/path-traversal-library
 * @tags security
 *       external/cwe/cwe-022
 */
import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider function parameters as sources for a library analysis
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("builtins").getMember("open").getACall() or
        call = API::moduleImport("io").getMember("open").getACall() or
        call = API::moduleImport("pathlib").getMember("Path").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTraversalFlow::flow(source, sink)
select sink, "File access depends on library parameter $@.", source, source.toString()

/**
 * @name CLI Path Traversal
 * @description Detects path traversal from argparse to file open in CLI
 * @kind path-problem
 * @problem.severity error
 * @id py/cli-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module CliPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // argparse return values
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module CliPathTraversalFlow = TaintTracking::Global<CliPathTraversalConfig>;
import CliPathTraversalFlow::PathGraph

from CliPathTraversalFlow::PathNode source, CliPathTraversalFlow::PathNode sink
where CliPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from CLI argument $@.", source.getNode(), "source"

/**
 * @name Command Injection from Library Parameters
 * @description Detects usage of subprocess or os.system with input from library parameters
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-param
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(SystemCommandExecution sce).getCommand()
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from parameter $@.", source.getNode(), "parameter"

